-- V5__product_images.sql — product photos stored in the database, so every computer sees the same picture.
-- One picture per product. The Owner uploads real photos (JPG/PNG/WebP, max 2 MB, ERR-PRD-006) on the
-- Product screen; until then each seeded product has a generated sample picture (is_placeholder = TRUE).
-- Generated by scripts/make_placeholder_images.py — edit that script, not the INSERT below.

CREATE TABLE product_image (
  product_id     BIGINT PRIMARY KEY REFERENCES product(product_id),
  content_type   VARCHAR(30) NOT NULL
                 CONSTRAINT chk_img_type CHECK (content_type IN ('image/jpeg','image/png','image/webp','image/svg+xml')),
  data           BYTEA NOT NULL,
  is_placeholder BOOLEAN NOT NULL DEFAULT FALSE,
  updated_by     BIGINT NULL REFERENCES app_user(user_id),
  updated_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT chk_img_size CHECK (octet_length(data) BETWEEN 1 AND 2097152)
);

